<?php
/* Lumiere trip-builder DEPLOY — schema + hotel/distance/point import + swap /build template.
   Self-contained. Safe to re-run (idempotent). Prints a report at the end. */
error_reporting(E_ALL & ~E_DEPRECATED & ~E_WARNING);
$DB_HOST=getenv('DB_HOST')?:"localhost";$DB_NAME=getenv('DB_NAME')?:"u406847900_lumiere_exp";$DB_USER=getenv('DB_USER')?:"u406847900_lumiere_exp";$DB_PASS=getenv('DB_PASS')?:"";
$report=[];
function rp(&$r,$m){$r[]=$m;echo $m."\n";}
try{ $pdo=new PDO("mysql:host=$DB_HOST;dbname=$DB_NAME;charset=utf8mb4",$DB_USER,$DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]); }
catch(Throwable $e){ die("DB CONNECT FAIL: ".$e->getMessage()."\n"); }

// 1. schema
$pdo->exec("CREATE TABLE IF NOT EXISTS tb_build_hotels (id INT AUTO_INCREMENT PRIMARY KEY, location VARCHAR(120) NOT NULL, name VARCHAR(200) NOT NULL, star TINYINT NOT NULL DEFAULT 3, room_categories VARCHAR(255) DEFAULT '', price_range VARCHAR(120) DEFAULT '', address VARCHAR(255) DEFAULT '', contact VARCHAR(120) DEFAULT '', active TINYINT NOT NULL DEFAULT 1, sort INT NOT NULL DEFAULT 0, KEY idx_loc(location), KEY idx_active(active)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$pdo->exec("CREATE TABLE IF NOT EXISTS tb_distances (id INT AUTO_INCREMENT PRIMARY KEY, from_loc VARCHAR(120) NOT NULL, to_loc VARCHAR(120) NOT NULL, km INT NOT NULL DEFAULT 0, UNIQUE KEY uniq_pair(from_loc,to_loc)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$pdo->exec("CREATE TABLE IF NOT EXISTS tb_points (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, active TINYINT NOT NULL DEFAULT 1, sort INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
rp($report,"schema ok");

// 2. hotels
$hotels=json_decode(gzdecode(base64_decode("")),true);
$ins=$pdo->prepare("INSERT INTO tb_build_hotels (location,name,star,room_categories,price_range,address,contact,active,sort) SELECT ?,?,?,?,?,?,?,1,? FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tb_build_hotels WHERE location=? AND name=?)");
$n=0;$s=0;
foreach($hotels as $hh){$s++;$ins->execute([$hh['location'],$hh['name'],$hh['star'],$hh['rooms'],$hh['price'],$hh['address'],$hh['contact'],$s,$hh['location'],$hh['name']]);$n+=$ins->rowCount();}
rp($report,"hotels inserted: $n (of ".count($hotels)." ; existing skipped)");

// 3. distances (both directions)
$dl=json_decode('[["Kochi", "Munnar", 130], ["Kochi", "Thekkady", 150], ["Kochi", "Alleppey", 55], ["Kochi", "Kumarakom", 55], ["Kochi", "Wayanad", 250], ["Kochi", "Kovalam", 220], ["Kochi", "Varkala", 185], ["Kochi", "Vagamon", 100], ["Kochi", "Trivandrum", 200], ["Kochi", "Calicut", 185], ["Kochi", "Bekal", 370], ["Kochi", "Guruvayoor", 90], ["Kochi", "Athirappilly", 70], ["Munnar", "Thekkady", 90], ["Munnar", "Alleppey", 170], ["Munnar", "Kumarakom", 145], ["Munnar", "Wayanad", 350], ["Munnar", "Kovalam", 290], ["Munnar", "Varkala", 270], ["Munnar", "Vagamon", 95], ["Munnar", "Trivandrum", 270], ["Munnar", "Calicut", 300], ["Munnar", "Bekal", 480], ["Munnar", "Guruvayoor", 200], ["Munnar", "Athirappilly", 140], ["Thekkady", "Alleppey", 145], ["Thekkady", "Kumarakom", 115], ["Thekkady", "Wayanad", 400], ["Thekkady", "Kovalam", 220], ["Thekkady", "Varkala", 200], ["Thekkady", "Vagamon", 60], ["Thekkady", "Trivandrum", 210], ["Thekkady", "Calicut", 330], ["Thekkady", "Bekal", 510], ["Thekkady", "Guruvayoor", 230], ["Thekkady", "Athirappilly", 190], ["Alleppey", "Kumarakom", 30], ["Alleppey", "Wayanad", 300], ["Alleppey", "Kovalam", 160], ["Alleppey", "Varkala", 120], ["Alleppey", "Vagamon", 100], ["Alleppey", "Trivandrum", 155], ["Alleppey", "Calicut", 235], ["Alleppey", "Bekal", 420], ["Alleppey", "Guruvayoor", 140], ["Alleppey", "Athirappilly", 120], ["Kumarakom", "Wayanad", 300], ["Kumarakom", "Kovalam", 170], ["Kumarakom", "Varkala", 130], ["Kumarakom", "Vagamon", 85], ["Kumarakom", "Trivandrum", 165], ["Kumarakom", "Calicut", 235], ["Kumarakom", "Bekal", 420], ["Kumarakom", "Guruvayoor", 145], ["Kumarakom", "Athirappilly", 125], ["Wayanad", "Kovalam", 470], ["Wayanad", "Varkala", 430], ["Wayanad", "Vagamon", 340], ["Wayanad", "Trivandrum", 450], ["Wayanad", "Calicut", 85], ["Wayanad", "Bekal", 210], ["Wayanad", "Guruvayoor", 170], ["Wayanad", "Athirappilly", 230], ["Kovalam", "Varkala", 55], ["Kovalam", "Vagamon", 230], ["Kovalam", "Trivandrum", 15], ["Kovalam", "Calicut", 400], ["Kovalam", "Bekal", 590], ["Kovalam", "Guruvayoor", 310], ["Kovalam", "Athirappilly", 290], ["Varkala", "Vagamon", 200], ["Varkala", "Trivandrum", 50], ["Varkala", "Calicut", 360], ["Varkala", "Bekal", 550], ["Varkala", "Guruvayoor", 270], ["Varkala", "Athirappilly", 255], ["Vagamon", "Trivandrum", 230], ["Vagamon", "Calicut", 280], ["Vagamon", "Bekal", 470], ["Vagamon", "Guruvayoor", 190], ["Vagamon", "Athirappilly", 150], ["Trivandrum", "Calicut", 385], ["Trivandrum", "Bekal", 580], ["Trivandrum", "Guruvayoor", 300], ["Trivandrum", "Athirappilly", 270], ["Calicut", "Bekal", 190], ["Calicut", "Guruvayoor", 100], ["Calicut", "Athirappilly", 200], ["Bekal", "Guruvayoor", 290], ["Bekal", "Athirappilly", 390], ["Guruvayoor", "Athirappilly", 110]]',true);
$di=$pdo->prepare("INSERT IGNORE INTO tb_distances (from_loc,to_loc,km) VALUES (?,?,?)");
$dn=0;foreach($dl as $d){$di->execute([$d[0],$d[1],$d[2]]);$dn+=$di->rowCount();$di->execute([$d[1],$d[0],$d[2]]);$dn+=$di->rowCount();}
rp($report,"distances inserted: $dn");

// 4. points
$pl=json_decode('["Cochin Airport (COK)", "Ernakulam Junction (South), Kochi", "Ernakulam Town (North)", "Vyttila Mobility Hub, Kochi", "Kochi City", "Trivandrum Central", "Trivandrum Airport (TRV)", "Kovalam", "Calicut Airport (CCJ)", "Kozhikode Railway", "Munnar", "Thekkady", "Alleppey", "Kumarakom", "Wayanad", "Varkala", "Vagamon", "Bekal", "Guruvayoor", "Athirappilly"]',true);
$pi=$pdo->prepare("INSERT INTO tb_points (name,active,sort) SELECT ?,1,? FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tb_points WHERE name=?)");
$pn=0;$k=0;foreach($pl as $p){$k++;$pi->execute([$p,$k,$p]);$pn+=$pi->rowCount();}
rp($report,"points inserted: $pn");

// 5. locate web root + swap build.php
$cands=["/var/www/lumiere/experience","/var/www/lumiere","/var/www/html/experience","/var/www/html"];
$root="";foreach($cands as $c){ if(is_file("$c/templates/build.php")){ $root=$c; break; } }
if(!$root){ foreach($cands as $c){ if(is_dir("$c/templates")){ $root=$c; break; } } }
if(!$root){ rp($report,"WEBROOT NOT FOUND — build.php NOT written. Checked: ".implode(", ",$cands)); }
else{
  rp($report,"webroot: $root");
  $tpl="$root/templates/build.php";
  if(is_file($tpl)){ @copy($tpl,$tpl.".bak.deploy"); rp($report,"backed up existing build.php -> build.php.bak.deploy"); }
  $newtpl=gzdecode(base64_decode(""));
  $ok=@file_put_contents($tpl,$newtpl);
  rp($report, $ok!==false ? "build.php written (".strlen($newtpl)." bytes)" : "FAILED writing build.php (permissions?)");
  // show api/build.php field handling for verification
  $api="$root/api/build.php";
  if(is_file($api)){ rp($report,"--- api/build.php (first 3500 chars) ---"); echo substr(file_get_contents($api),0,3500)."\n--- end api ---\n"; }
  else rp($report,"api/build.php not found at $api");
  // clear page cache
  $cache="$root/cache"; $cc=0;
  if(is_dir($cache)){ foreach(glob("$cache/*.html") as $f){ @unlink($f); $cc++; } }
  rp($report,"cache files cleared: $cc");
}
rp($report,"DONE");
